import java.util.*;
import java.io.*;

public class CFA5 {

    public static void main(String[] args) throws IOException {
        new CFA5().run();
    }

    void run() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter out = new PrintWriter(System.out);
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            if (n > m) { int t = n; n = m; m = t; }

            Action action = () -> {
                long res = (long)n * m;
                if (n == 1) {
                    m--;
                    int[] left = {0,0,0,2,4,6};
                    return m / 6 * 6L + left[m % 6];
                } else if (n == 2) {
                    return m < 20 ? (long)bruteForce(n, m) : (long)n * m;
                } else if (n == 3) {
                    if (m < 20) return (long)bruteForce(n, m);
                    if ((res & 1) == 1) res--;
                    return res;
                } else {
                    if (res < 1000) return (long)bruteForce(n, m);
                    if ((res & 1) == 1) res--;
                    return res;
                }
            };
            out.println(action.compute());
            out.close();
        }
    }

    interface Action {
        long compute();
    }

    int bruteForce(int n, int m) {
        List<Point> even = new ArrayList<>();
        List<Point> odd = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i + j) % 2 == 0) even.add(new Point(i, j));
                else odd.add(new Point(i, j));
            }
        }
        int es = even.size(), os = odd.size();
        boolean[][] graph = new boolean[es][os];
        for (int i = 0; i < es; i++) {
            for (int j = 0; j < os; j++) {
                if (even.get(i).dist(odd.get(j)) == 3) graph[i][j] = true;
            }
        }
        return 2 * maxMatching(graph);
    }

    class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        int dist(Point o) { return Math.abs(x - o.x) + Math.abs(y - o.y); }
    }

    int maxMatching(boolean[][] g) {
        int n1 = g.length, n2 = n1 == 0 ? 0 : g[0].length;
        int[] matchR = new int[n2];
        Arrays.fill(matchR, -1);
        int res = 0;
        for (int u = 0; u < n1; u++) {
            if (dfs(g, u, new boolean[n1], matchR)) res++;
        }
        return res;
    }

    boolean dfs(boolean[][] g, int u, boolean[] vis, int[] matchR) {
        for (int v = 0; v < matchR.length; v++) {
            if (g[u][v] && !vis[v]) {
                vis[v] = true;
                if (matchR[v] == -1 || dfs(g, matchR[v], vis, matchR)) {
                    matchR[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}
